from decimal import Decimal, ROUND_HALF_UP, InvalidOperation
from typing import Iterable, Union

NumberLike = Union["Money", Decimal, int, float, str]

CENT = Decimal("0.01")
_DEFAULT_CURRENCY = "USD"


def _to_decimal(value: NumberLike) -> Decimal:
    """Convert supported inputs to Decimal without losing integer precision."""
    if isinstance(value, Money):
        return value.amount
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int):
        return Decimal(value)
    if isinstance(value, float):
        # Use str() to avoid binary float artifacts leaking into Decimal.
        return Decimal(str(value))
    if isinstance(value, str):
        text = value.strip()
        if not text:
            raise ValueError("money value cannot be empty")
        # Strip common currency symbols/codes to be forgiving.
        for token in ("$", "USD", "usd"):
            text = text.replace(token, "")
        text = text.replace(",", "").strip()
        return Decimal(text)
    raise TypeError(f"unsupported money value type: {type(value)!r}")


def _quantize(value: Decimal) -> Decimal:
    """Normalize to two decimal places using standard financial rounding."""
    return value.quantize(CENT, rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str = _DEFAULT_CURRENCY

    def __post_init__(self) -> None:
        try:
            normalized = _quantize(_to_decimal(self.amount))
        except (InvalidOperation, ValueError) as exc:
            raise ValueError(f"invalid money amount: {self.amount!r}") from exc

        curr = (self.currency or "").strip().upper()
        if not curr:
            raise ValueError("currency must be a non-empty string")

        object.__setattr__(self, "amount", normalized)
        object.__setattr__(self, "currency", curr)

    @classmethod
    def from_minor(cls, minor_units: int, currency: str = _DEFAULT_CURRENCY) -> "Money":
        return cls(Decimal(minor_units) / 100, currency)

    def as_minor(self) -> int:
        return int((self.amount * 100).to_integral_value(rounding=ROUND_HALF_UP))

    def _coerce_other(self, other: NumberLike) -> "Money":
        if isinstance(other, Money):
            return other
        return Money(_to_decimal(other), self.currency)

    def _ensure_same_currency(self, other: "Money") -> None:
        if self.currency != other.currency:
            raise ValueError(f"currency mismatch: {self.currency} != {other.currency}")

    def __add__(self, other: NumberLike) -> "Money":
        rhs = self._coerce_other(other)
        self._ensure_same_currency(rhs)
        return Money(self.amount + rhs.amount, self.currency)

    def __sub__(self, other: NumberLike) -> "Money":
        rhs = self._coerce_other(other)
        self._ensure_same_currency(rhs)
        return Money(self.amount - rhs.amount, self.currency)

    def __mul__(self, factor: Union[int, float, Decimal]) -> "Money":
        return Money(self.amount * _to_decimal(factor), self.currency)

    def __rmul__(self, factor: Union[int, float, Decimal]) -> "Money":
        return self.__mul__(factor)

    def __truediv__(self, divisor: Union[int, float, Decimal]) -> "Money":
        d = _to_decimal(divisor)
        if d == 0:
            raise ZeroDivisionError("cannot divide money by zero")
        return Money(self.amount / d, self.currency)

    def __neg__(self) -> "Money":
        return Money(-self.amount, self.currency)

    def __pos__(self) -> "Money":
        return self

    def __abs__(self) -> "Money":
        return Money(abs(self.amount), self.currency)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Money):
            return False
        return self.currency == other.currency and self.amount == other.amount

    def __lt__(self, other: "Money") -> bool:
        self._ensure_same_currency(other)
        return self.amount < other.amount

    def __le__(self, other: "Money") -> bool:
        self._ensure_same_currency(other)
        return self.amount <= other.amount

    def __gt__(self, other: "Money") -> bool:
        self._ensure_same_currency(other)
        return self.amount > other.amount

    def __ge__(self, other: "Money") -> bool:
        self._ensure_same_currency(other)
        return self.amount >= other.amount

    def __str__(self) -> str:
        return f"{self.currency} {self.amount:.2f}"

    def __repr__(self) -> str:
        return f"Money(amount=Decimal('{self.amount}'), currency='{self.currency}')"

    def __format__(self, format_spec: str) -> str:
        if format_spec:
            return format(self.amount, format_spec)
        return f"{self.amount:.2f}"

    def to_decimal(self) -> Decimal:
        return self.amount

    def round(self, ndigits: int = 2) -> "Money":
        if ndigits < 0:
            raise ValueError("ndigits must be >= 0")
        quant = Decimal("1").scaleb(-ndigits)
        return Money(self.amount.quantize(quant, rounding=ROUND_HALF_UP), self.currency)

    def percent(self, pct: Union[int, float, Decimal]) -> "Money":
        return Money(self.amount * _to_decimal(pct) / Decimal("100"), self.currency)

    def allocate(self, ratios: Iterable[int]) -> list["Money"]:
        parts = list(ratios)
        if not parts:
            raise ValueError("ratios cannot be empty")
        if any(r < 0 for r in parts):
            raise ValueError("ratios cannot contain negative values")
        total = sum(parts)
        if total <= 0:
            raise ValueError("sum of ratios must be > 0")

        total_cents = self.as_minor()
        raw = [total_cents * r / total for r in parts]
        floors = [int(x) for x in raw]
        remainder = total_cents - sum(floors)

        # Distribute remaining cents to largest fractional parts first.
        frac_order = sorted(
            range(len(parts)),
            key=lambda i: (raw[i] - floors[i]),
            reverse=True,
        )
        for i in frac_order[:remainder]:
            floors[i] += 1

        return [Money.from_minor(c, self.currency) for c in floors]


def money(value: NumberLike = 0, currency: str = _DEFAULT_CURRENCY) -> Money:
    """Factory function used by tests and callers that prefer function-style API."""
    return Money(_to_decimal(value), currency)


def parse_money(value: NumberLike, currency: str = _DEFAULT_CURRENCY) -> Money:
    return money(value, currency)


def format_money(value: NumberLike, currency: str = _DEFAULT_CURRENCY) -> str:
    return str(money(value, currency))
