    lowered = text.lower()
    placeholder_tokens = ("todo", "fixme", "pass", "blocked", "placeholder")
    if not any(tok in lowered for tok in placeholder_tokens):
        score += 0.20

    if any(ch.isalpha() for ch in text):
        score += 0.10

    return min(score, 1.0)


