"""
repair_loop.py

Fast-verify repair loop targeting primary_quality >= 0.75
within at most 3 iterations.
"""

from __future__ import annotations

from typing import Any, Callable, Dict, List, Mapping

QUALITY_TARGET = 0.75
MAX_ITERATIONS = 3


def _clamp_quality(value: Any) -> float:
    """Convert value to float in [0.0, 1.0]."""
    try:
        quality = float(value)
    except (TypeError, ValueError):
        return 0.0
    if quality < 0.0:
        return 0.0
    if quality > 1.0:
        return 1.0
    return quality


def _safe_int(value: Any, default: int) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def _normalize_diagnostics(raw: Any) -> Dict[str, Any]:
    """
    Normalize evaluator output to a diagnostics dict with primary_quality.

    Supported evaluator outputs:
    - dict-like: {"primary_quality": 0.8, ...}
    - numeric: 0.8
    - anything else: treated as 0.0 quality
    """
    if isinstance(raw, Mapping):
        diagnostics: Dict[str, Any] = dict(raw)
    elif isinstance(raw, (int, float)):
        diagnostics = {"primary_quality": raw}
    else:
        diagnostics = {}

    if "primary_quality" not in diagnostics:
        # Common fallback keys used by evaluators.
        for key in ("quality", "score", "primaryScore"):
            if key in diagnostics:
                diagnostics["primary_quality"] = diagnostics[key]
                break

    diagnostics["primary_quality"] = _clamp_quality(diagnostics.get("primary_quality", 0.0))
    return diagnostics


def _call_propose_fix(
    propose_fix: Callable[..., str],
    current_module: str,
    last_diagnostics: Dict[str, Any],
    iteration: int,
) -> str:
    """
    Call proposer with flexible arity:
    - propose_fix(current, last_diag, iteration)
    - propose_fix(current, last_diag)
    - propose_fix(current)
    """
    candidate: Any
    try:
        candidate = propose_fix(current_module, last_diagnostics, iteration)
    except TypeError:
        try:
            candidate = propose_fix(current_module, last_diagnostics)
        except TypeError:
            candidate = propose_fix(current_module)

    if not isinstance(candidate, str) or not candidate.strip():
        return current_module
    return candidate


def _call_evaluate_quality(
    evaluate_quality: Callable[[str], Any],
    module_source: str,
) -> Dict[str, Any]:
    try:
        raw = evaluate_quality(module_source)
    except Exception:
        raw = {"primary_quality": 0.0, "error": "evaluate_quality_failed"}
    return _normalize_diagnostics(raw)


def _build_outcome(
    success: bool,
    final_module: str,
    final_quality: float,
    iterations_used: int,
    history: List[Dict[str, Any]],
) -> Dict[str, Any]:
    return {
        "success": bool(success),
        "final_module": final_module,
        "final_quality": _clamp_quality(final_quality),
        "iterations_used": int(iterations_used),
        "history": history,
    }


def run_repair_loop(
    initial_module: str,
    propose_fix: Callable[..., str],
    evaluate_quality: Callable[[str], Any],
    target_quality: float = QUALITY_TARGET,
    max_iterations: int = MAX_ITERATIONS,
) -> Dict[str, Any]:
    """
    Execute a bounded repair loop.

    Args:
        initial_module: Current module source code.
        propose_fix: Callable that proposes a full revised module source.
        evaluate_quality: Callable that evaluates module quality.
        target_quality: Success threshold for primary_quality.
        max_iterations: Requested maximum attempts; hard-capped at 3.

    Returns:
        Dict with keys:
          - success: bool
          - final_module: str
          - final_quality: float
          - iterations_used: int
          - history: List[dict]
    """
    current = initial_module if isinstance(initial_module, str) else str(initial_module or "")
    target = _clamp_quality(target_quality)

    requested = _safe_int(max_iterations, MAX_ITERATIONS)
    if requested < 0:
        requested = 0
    budget = min(requested, MAX_ITERATIONS)

    history: List[Dict[str, Any]] = []
    last_diag: Dict[str, Any] = {}

    # Fast-verify current module before attempting any repair.
    seed_diag = _call_evaluate_quality(evaluate_quality, current)
    seed_quality = _clamp_quality(seed_diag.get("primary_quality", 0.0))

    best_module = current
    best_quality = seed_quality

    if seed_quality >= target:
        return _build_outcome(
            success=True,
            final_module=current,
            final_quality=seed_quality,
            iterations_used=0,
            history=history,
        )

    for iteration in range(1, budget + 1):
        try:
            candidate = _call_propose_fix(propose_fix, current, last_diag, iteration)
        except Exception:
            candidate = current

        diagnostics = _call_evaluate_quality(evaluate_quality, candidate)
        quality = _clamp_quality(diagnostics.get("primary_quality", 0.0))

        history.append(
            {
                "iteration": iteration,
                "candidate_module": candidate,
                "primary_quality": quality,
                "diagnostics": diagnostics,
            }
        )

        current = candidate
        last_diag = diagnostics

        if quality > best_quality:
            best_quality = quality
            best_module = candidate

        if quality >= target:
            return _build_outcome(
                success=True,
                final_module=candidate,
                final_quality=quality,
                iterations_used=iteration,
                history=history,
            )

    return _build_outcome(
        success=best_quality >= target,
        final_module=best_module,
        final_quality=best_quality,
        iterations_used=budget,
        history=history,
    )


